cd /tmp/vally-eval-trial-MNsCJC && mkdir -p docs/features/checkout-pricing .copilot-tracking/skraft-plans/pricing/details/2026-08-12 tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > docs/features/checkout-pricing/loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty discount

  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver and Gold (AC-1 to AC-4), every value below comes from the acceptance criteria.
  # NOT DECIDED: Platinum tier. The business has not agreed a reduction, so there is no scenario for it
  # and none may be invented until the business gives an expected value.
  # NOT DECIDED: how a reduction is rounded for any subtotal other than the 7 cents of AC-4.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price for a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer is charged a whole cent amount for a small basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_the_Bronze_price_for_a_basket()
    {
        // Bronze customer is charged the Bronze price for a basket
        var calculateLoyaltyDiscount = new CalculateLoyaltyDiscount();

        var quote = calculateLoyaltyDiscount.Handle(
            new CalculateLoyaltyDiscountQuery(SubtotalCents: 10000, LoyaltyTier: LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --no-restore --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" 2>&1 | tail -25

